// ─── Module 0: Business Ownership ───────────────────────────────────────────
LESSON_DB.business.m0 = {
  0: {emoji:"🍔", subtitle:"Grade 10 · One owner, all the risk, all the profit",
    illusText:"Mam' Thoko's kota shop: her money, her decisions, her risk.",
    hook:{title:"Mam' Thoko's kota shop", body:"Mam' Thoko opens a kota stand outside a Soweto taxi rank with R8 000 of her savings. She decides the menu, the prices and the hours, and every rand of profit is hers. But when a supplier isn't paid, the supplier can come after her <em>personal</em> savings and furniture too. That's the deal of a <strong>sole trader</strong>: total control, total risk."},
    intro:"A <strong>sole trader</strong> (sole proprietor) is a business owned by one person. It is the easiest form to start — there's no CIPC registration of the business itself, though the owner must declare income to SARS and get any licences needed (e.g. a trading licence or food certificate). The business is <strong>not a separate legal person</strong>: the owner has <strong>unlimited liability</strong>, meaning personal assets can be used to pay business debts. Profits are taxed as the owner's personal income. Most spaza shops, hair salons, mechanics and street vendors in South Africa are sole traders.",
    concepts:[
      {t:"green", title:"✅ Advantages", body:"Easy and cheap to start, quick decisions, owner keeps all profits, close contact with customers, few legal requirements."},
      {t:"teal", title:"⚠️ Disadvantages", body:"Unlimited liability, limited capital, owner carries all the work and risk, no continuity — the business ends if the owner dies."},
      {t:"gold", title:"🔁 Continuity", body:"No continuity means the business legally ends with the owner. Planning for succession matters."},
    ],
    examples:[
      {title:"Liability", body:"Mam' Thoko's business owes a supplier R15 000 and has only R5 000 in its account.", answer:"With <strong>unlimited liability</strong>, she must pay the other R10 000 from her personal savings or assets."},
      {title:"Is it a sole trader?", body:"Sipho runs a phone-repair stall alone and keeps all profits.", answer:"<strong>Yes</strong> — one owner, all profits and all risk."},
      {title:"Tax", body:"How is a sole trader's profit taxed?", answer:"As the owner's <strong>personal income</strong>, at personal income-tax rates."},
    ],
    mistakes:["Thinking a sole trader must have only one worker — it can employ many people; it has one owner.","Confusing limited and unlimited liability.","Saying a sole trader is a separate legal person."],
    callout:{title:"Informal economy", body:"Millions of South Africans earn a living as sole traders in the informal sector — spaza shops, street vendors, hair braiders and car guards are all businesses."},
    activity:"Think of three sole traders in your community. For each, name one advantage and one risk of their form of ownership.",
    activityAnswer:"Example: a spaza shop owner — advantage: quick decisions on stock; risk: personal assets at stake if debts pile up. Answers will vary.",
    examTip:"When comparing forms of ownership, always cover liability, legal personality, continuity, capital and taxation.",
    keyterms:[{w:"Sole trader",d:"A business owned by one person"},{w:"Unlimited liability",d:"The owner is personally responsible for all business debts"},{w:"Continuity",d:"Whether a business continues to exist after the owner leaves or dies"}],
    quiz:[
      {q:"A sole trader has:",opts:["Limited liability","Unlimited liability","No liability","Shared liability with shareholders"],a:1,et:"Personal assets can be used to pay debts."},
      {q:"Which is an advantage of a sole trader?",opts:["Continuity","Quick decision-making","Limited liability","Easy to raise large capital"],a:1,et:"One owner decides."},
      {q:"A sole trader's profit is taxed as:",opts:["Company tax","The owner's personal income","VAT only","It is not taxed"],a:1,et:"At personal income-tax rates."},
    ],
    conclusion:"A sole trader is the simplest business — full control, full profit and full risk. Know both sides."},

  1: {emoji:"🤝", subtitle:"Grade 10 · Sharing the business, the profit and the problems",
    illusText:"Two friends, one car wash — and a partnership agreement that saved their friendship.",
    hook:{title:"The car-wash partnership", body:"Lerato and Kabelo start a car wash together. Lerato puts in R30 000 for equipment; Kabelo does most of the work. After a good year with R120 000 profit, they argue: how should it be split? Luckily, they wrote a <strong>partnership agreement</strong> before they started — profits are shared 3 : 2. Lerato gets R72 000 and Kabelo R48 000. Agreements protect friendships."},
    intro:"A <strong>partnership</strong> is a business owned by two or more people who share profits, losses and decisions. A written <strong>partnership agreement</strong> should set out each partner's contribution, profit-sharing ratio, duties, how decisions are made and what happens if a partner leaves. A partnership is <strong>not a separate legal person</strong>, and partners have <strong>unlimited and joint liability</strong>: each partner can be held responsible for all the partnership's debts. When a partner leaves or dies, the partnership ends and a new one must be formed. (Older textbooks give a limit of 20 partners, from previous company law.)",
    concepts:[
      {t:"green", title:"✅ Advantages", body:"More capital and skills than a sole trader, shared workload and decisions, easy to set up."},
      {t:"teal", title:"⚠️ Disadvantages", body:"Unlimited and joint liability, possible disagreements, no continuity, profits must be shared."},
      {t:"gold", title:"📄 The agreement", body:"Covers capital, profit ratio, roles, decision-making, dispute resolution and exit rules."},
    ],
    examples:[
      {title:"Share the profit", body:"Profit R120 000; ratio 3 : 2.", answer:"5 parts → R24 000 each. Lerato 3 × 24 000 = <strong>R72 000</strong>; Kabelo 2 × 24 000 = <strong>R48 000</strong>."},
      {title:"Joint liability", body:"The partnership owes R40 000 and Kabelo has no money. Who pays?", answer:"<strong>Lerato can be held liable for the full amount</strong> — partners are jointly liable."},
      {title:"Continuity", body:"What happens if Kabelo leaves?", answer:"The partnership <strong>ends</strong>; Lerato can form a new partnership or continue as a sole trader."},
    ],
    formula:"Partner's share = Profit × (partner's ratio ÷ total ratio)",
    mistakes:["Assuming profits are always shared equally — the agreement decides.","Thinking a partnership has limited liability.","Forgetting that a partnership ends when a partner leaves."],
    callout:{title:"Choose partners carefully", body:"Trust, shared values and complementary skills matter more than friendship alone."},
    activity:"Three partners share a profit of R90 000 in the ratio 4 : 3 : 2. Calculate each share.",
    activityAnswer:"9 parts → R10 000 each. Shares: <strong>R40 000, R30 000 and R20 000</strong>.",
    examTip:"List at least four items a partnership agreement should contain — this is a common short question.",
    keyterms:[{w:"Partnership",d:"A business owned by two or more people"},{w:"Joint liability",d:"Each partner can be held responsible for all the debts"},{w:"Partnership agreement",d:"Contract setting out the partners' rights and duties"}],
    quiz:[
      {q:"Partners have:",opts:["Limited liability","Unlimited and joint liability","No liability","Liability only for their own share"],a:1,et:"Each can be held responsible for all debts."},
      {q:"Profit R60 000 shared 2 : 1. The larger share is:",opts:["R20 000","R30 000","R40 000","R60 000"],a:2,et:"3 parts → R20 000 each → 2 × 20 000."},
      {q:"A partnership ends when:",opts:["It makes a loss","A partner leaves or dies","It hires workers","It pays tax"],a:1,et:"No continuity."},
    ],
    conclusion:"Partnerships combine money and skills — and shared risk. A clear written agreement is essential."},

  2: {emoji:"🏢", subtitle:"Grade 10–11 · (Pty) Ltd — separate, protected and private",
    illusText:"Register with CIPC and your business becomes a separate legal person.",
    hook:{title:"From side hustle to (Pty) Ltd", body:"Ayanda's natural hair products sell so well online that a retail chain wants to stock them. The buyer asks for a registered company and a tax number. Ayanda registers <strong>Ayanda Naturals (Pty) Ltd</strong> online with the CIPC. Now the business is a separate legal person: if it fails, her own house is protected. That protection is called <strong>limited liability</strong>."},
    intro:"A <strong>private company</strong> is registered with the <strong>Companies and Intellectual Property Commission (CIPC)</strong> under the <strong>Companies Act 71 of 2008</strong>. Its name ends in <strong>(Pty) Ltd</strong>. It is a <strong>separate legal person</strong> that can own property, sign contracts and be sued in its own name. Shareholders have <strong>limited liability</strong>: they can lose only what they invested. It needs at least one director and a <strong>Memorandum of Incorporation (MOI)</strong>. Shares <strong>cannot be offered to the public</strong> and are usually restricted in how they're transferred. It has <strong>continuity</strong> — it continues even if shareholders change. Companies pay <strong>company income tax</strong> (27% of taxable income for years ending on or after 31 March 2023).",
    concepts:[
      {t:"green", title:"🛡️ Limited liability", body:"Shareholders risk only their investment, not their personal assets."},
      {t:"teal", title:"⚖️ Legal personality", body:"The company itself owns assets, owes debts and can sue or be sued."},
      {t:"gold", title:"📋 More rules", body:"Registration, an MOI, annual returns to CIPC, proper records and possibly an audit or independent review."},
    ],
    examples:[
      {title:"Limited liability", body:"Ayanda invested R50 000. The company fails owing R200 000.", answer:"Ayanda can lose her <strong>R50 000 investment</strong>; creditors cannot claim her house (unless she signed personal surety)."},
      {title:"Company tax", body:"A company has a taxable income of R500 000 at 27%.", answer:"500 000 × 0.27 = <strong>R135 000</strong> company tax."},
      {title:"Continuity", body:"A shareholder sells her shares. Does the company end?", answer:"<strong>No</strong> — the company continues; it has continuity."},
    ],
    formula:"Company tax = Taxable income × 27%",
    mistakes:["Thinking a private company can sell shares on the JSE.","Forgetting that directors can be personally liable for reckless trading or signing surety.","Mixing up the MOI with a partnership agreement."],
    callout:{title:"Surety", body:"Banks often ask small-company owners to sign personal surety for loans — which removes the limited-liability protection for that debt."},
    activity:"List three things Ayanda needs to register a private company and two ongoing obligations afterwards.",
    activityAnswer:"Register: company name, at least one director, an MOI (standard or own) and registration with CIPC. Ongoing: annual returns to CIPC, tax returns to SARS, proper accounting records.",
    examTip:"Use the correct legal terms — CIPC, Companies Act 71 of 2008, MOI, separate legal person, limited liability.",
    keyterms:[{w:"Limited liability",d:"Owners can lose only what they invested"},{w:"CIPC",d:"Companies and Intellectual Property Commission"},{w:"MOI",d:"Memorandum of Incorporation — the company's founding document"}],
    quiz:[
      {q:"A private company's name ends with:",opts:["Ltd","(Pty) Ltd","Inc.","NPC"],a:1,et:"Private company."},
      {q:"Companies are registered with:",opts:["SARS","CIPC","SASSA","The JSE"],a:1,et:"Under the Companies Act 71 of 2008."},
      {q:"A private company:",opts:["Can offer shares to the public","Cannot offer shares to the public","Has unlimited liability","Ends when a shareholder leaves"],a:1,et:"Shares are private."},
    ],
    conclusion:"Registering a company protects the owner and helps the business grow — in exchange for more rules and records."},

  3: {emoji:"📈", subtitle:"Grade 10–11 · Ltd — owned by the public, listed on the JSE",
    illusText:"With a share-trading app, a learner can own a tiny piece of a JSE-listed company.",
    hook:{title:"Owning a piece of a bank", body:"Capitec started in 2001 and grew into one of South Africa's biggest banks by number of clients. It is a <strong>public company</strong> listed on the JSE — so anyone with a share-trading app can buy a small piece of it. Public companies raise huge amounts of money from many investors, but in return they must share their results with the world."},
    intro:"A <strong>public company</strong> is registered under the Companies Act, with a name ending in <strong>Ltd</strong> (Limited). It can <strong>offer shares to the public</strong>, usually by listing on a stock exchange such as the <strong>JSE</strong>. It needs at least <strong>three directors</strong> (and an audit committee), must have its financial statements <strong>audited</strong>, publish results and hold an <strong>annual general meeting (AGM)</strong>. Shareholders have <strong>limited liability</strong>, and shares are freely transferable. To raise money from the public, the company issues a <strong>prospectus</strong>. Other company types include personal liability companies (Inc.), state-owned companies (SOC Ltd — e.g. Eskom) and non-profit companies (NPC).",
    concepts:[
      {t:"green", title:"💰 Raising capital", body:"Selling shares to thousands of investors raises far more capital than any other form of ownership."},
      {t:"teal", title:"🔍 Transparency", body:"Audited annual reports, published results and AGMs keep shareholders informed and protect the public."},
      {t:"gold", title:"🏛️ Governance", body:"A board of directors manages on behalf of shareholders; the King IV code guides good governance."},
    ],
    examples:[
      {title:"Market value", body:"A company has 10 million shares trading at R25 each.", answer:"10 000 000 × 25 = <strong>R250 million</strong> market capitalisation."},
      {title:"Public or private?", body:"A company invites anyone to buy its shares through the JSE.", answer:"<strong>Public company (Ltd)</strong>."},
      {title:"Separation", body:"Why might shareholders and directors disagree?", answer:"Ownership and control are <strong>separated</strong>: directors manage, shareholders own — their interests can differ."},
    ],
    formula:"Market capitalisation = Number of shares × Share price",
    mistakes:["Confusing “public company” with a government-owned company.","Saying all public companies are listed — most are, but listing is a choice.","Forgetting the audit and AGM requirements."],
    callout:{title:"State-owned companies", body:"Eskom, Transnet and SAA are state-owned companies (SOC Ltd) — owned by government, not the public through shares."},
    activity:"Find a JSE-listed company you know (a retailer, bank or cellphone network). Identify its name ending, what it sells and one reason it chose to be public.",
    activityAnswer:"Example: Shoprite Holdings Ltd — groceries; it became public to raise capital for expansion across South Africa and Africa.",
    examTip:"Know the differences between private and public companies: shares to the public, minimum directors, audit, name ending.",
    keyterms:[{w:"Public company",d:"A company that may offer shares to the public (Ltd)"},{w:"Prospectus",d:"Document inviting the public to buy shares"},{w:"AGM",d:"Annual general meeting of shareholders"}],
    quiz:[
      {q:"A public company's name ends with:",opts:["(Pty) Ltd","Ltd","Inc.","CC"],a:1,et:"Limited."},
      {q:"Public companies must have at least:",opts:["1 director","2 directors","3 directors","10 directors"],a:2,et:"Plus an audit committee."},
      {q:"Eskom is a(n):",opts:["Public company","State-owned company","Sole trader","Partnership"],a:1,et:"SOC Ltd."},
    ],
    conclusion:"Public companies raise big money from many owners — and must open their books to everyone."},

  4: {emoji:"⚖️", subtitle:"Grade 10–11 · Choosing the right form of ownership",
    illusText:"As a business grows, the best form of ownership often changes.",
    hook:{title:"The growing bakery", body:"Nomsa started baking from home as a sole trader. Her sister joined and they became partners. Now a supermarket wants to stock their bread in 50 stores, and they need R2 million for a bigger oven and delivery vans. Which form of ownership suits them now? Choosing the right form is a strategic decision, not a formality."},
    intro:"Forms of ownership are compared on: <strong>number of owners</strong>, <strong>formation requirements</strong>, <strong>legal personality</strong>, <strong>liability</strong>, <strong>continuity</strong>, <strong>capital</strong>, <strong>management</strong> and <strong>taxation</strong>. Sole traders and partnerships are easy to start but have unlimited liability and no continuity. Private companies offer limited liability and continuity with more paperwork. Public companies can raise the most capital but face the strictest rules. The right choice depends on the size of the business, the risk involved, how much capital is needed and how much control the owners want to keep.",
    concepts:[
      {t:"green", title:"🧮 Capital", body:"Sole trader: owner's savings and loans. Partnership: partners' contributions. Companies: share capital — public companies from the public."},
      {t:"teal", title:"🛡️ Risk", body:"Unlimited liability (sole trader, partnership) vs limited liability (companies)."},
      {t:"gold", title:"🎛️ Control", body:"The more owners, the more control is shared — public companies separate ownership from management."},
    ],
    examples:[
      {title:"Nomsa's bakery", body:"They need R2 million and want to protect their homes.", answer:"A <strong>private company</strong> — limited liability, continuity, can bring in investors as shareholders while keeping control."},
      {title:"A one-person tutor", body:"Thabo tutors Maths after school.", answer:"<strong>Sole trader</strong> — low risk, low capital, simple to run."},
      {title:"Listing", body:"When would a business consider becoming public?", answer:"When it needs <strong>very large capital</strong> for expansion and can handle strict reporting rules."},
    ],
    mistakes:["Recommending a form of ownership without justifying it.","Saying one form is always best — it depends on the business.","Ignoring tax differences."],
    callout:{title:"Exam essays", body:"Business Studies essays often ask you to recommend a form of ownership for a case study. Link every recommendation to facts in the case."},
    activity:"A group of five friends wants to start a taxi business with R1.5 million and wants their personal assets protected. Recommend a form of ownership and give three reasons.",
    activityAnswer:"<strong>Private company</strong>: limited liability protects personal assets; continuity if a member leaves; easier to borrow as a registered company; up to many shareholders.",
    examTip:"Use a table in your planning, then write in paragraphs: criterion → explanation → link to the case study.",
    keyterms:[{w:"Form of ownership",d:"The legal structure of a business"},{w:"Legal personality",d:"Being recognised in law as a separate person"},{w:"Capital",d:"Money invested to start or grow a business"}],
    quiz:[
      {q:"Which forms have limited liability?",opts:["Sole trader and partnership","Private and public companies","Only partnerships","None"],a:1,et:"Companies are separate legal persons."},
      {q:"Which can raise the most capital?",opts:["Sole trader","Partnership","Private company","Public company"],a:3,et:"It can sell shares to the public."},
      {q:"Which has continuity?",opts:["Sole trader","Partnership","Private company","None"],a:2,et:"Companies continue when owners change."},
    ],
    conclusion:"There's no single best form of ownership — only the best fit for a business's size, risk and goals."},

  5: {emoji:"🌱", subtitle:"Grade 11–12 · Broad-Based Black Economic Empowerment",
    illusText:"A B-BBEE level can decide whether a small supplier wins a big contract.",
    hook:{title:"The catering contract", body:"Zinhle runs a small, 100% black-owned catering business in Polokwane. A mining company chooses her as a supplier and also mentors her through its supplier-development programme. Her business grows from 3 to 15 staff. That's <strong>B-BBEE</strong> in action — a policy designed to open the economy to people excluded by apartheid."},
    intro:"<strong>Broad-Based Black Economic Empowerment (B-BBEE)</strong> is government policy to increase black South Africans' participation in the economy. It is set out in the <strong>B-BBEE Act 53 of 2003</strong> (amended in 2013) and the <strong>Codes of Good Practice</strong>. Businesses are measured on a <strong>scorecard</strong> with elements: <strong>ownership</strong>, <strong>management control</strong>, <strong>skills development</strong>, <strong>enterprise and supplier development</strong> and <strong>socio-economic development</strong>. The score gives a <strong>B-BBEE level</strong> from 1 (best) to 8. Exempted micro-enterprises (annual turnover up to R10 million) get an automatic level. A good level helps businesses win government and corporate contracts.",
    concepts:[
      {t:"green", title:"🎯 Purpose", body:"Redress apartheid-era exclusion by broadening ownership, management, skills and business opportunities."},
      {t:"teal", title:"📊 Scorecard", body:"Ownership, management control, skills development, enterprise and supplier development, socio-economic development."},
      {t:"gold", title:"⚖️ Debate", body:"Supporters point to new black-owned businesses and skills; critics point to “fronting” and benefits going to a connected few."},
    ],
    examples:[
      {title:"Supplier development", body:"A mining company trains and buys from a small black-owned supplier.", answer:"This earns points under <strong>enterprise and supplier development</strong>."},
      {title:"Fronting", body:"A company lists a black person as a director but gives them no real role or share of profit.", answer:"This is <strong>fronting</strong> — an illegal, dishonest way to gain B-BBEE points."},
      {title:"Why it matters", body:"Why would a supplier want a good B-BBEE level?", answer:"Customers with B-BBEE targets <strong>prefer high-level suppliers</strong>, so it helps win contracts."},
    ],
    mistakes:["Thinking B-BBEE is only about ownership — there are several scorecard elements.","Ignoring fronting and criticism in evaluation questions.","Confusing level 1 (best) with level 8."],
    callout:{title:"Evaluate, don't preach", body:"Business Studies asks you to evaluate policies: give positive and negative impacts with examples, then conclude."},
    activity:"Suggest three ways a small business in your area could improve its B-BBEE score.",
    activityAnswer:"Examples: train staff (skills development), buy from black-owned local suppliers (preferential procurement / supplier development), support a community project (socio-economic development).",
    examTip:"Name the scorecard elements exactly and give an example of how a business can earn points for each.",
    keyterms:[{w:"B-BBEE",d:"Broad-Based Black Economic Empowerment"},{w:"Scorecard",d:"Measures a business's B-BBEE contribution"},{w:"Fronting",d:"Faking black ownership or control to gain B-BBEE points"}],
    quiz:[
      {q:"The best B-BBEE level is:",opts:["Level 1","Level 4","Level 8","Level 10"],a:0,et:"Levels run from 1 (best) to 8."},
      {q:"Training staff earns points under:",opts:["Ownership","Skills development","Fronting","Tax"],a:1,et:"A scorecard element."},
      {q:"Fronting is:",opts:["A legal strategy","Faking black ownership or control","A type of marketing","A tax"],a:1,et:"It's illegal."},
    ],
    conclusion:"B-BBEE aims to open the economy. Understand the scorecard — and evaluate both its successes and its failures."},
};

// ─── Module 1: Business Operations ──────────────────────────────────────────
LESSON_DB.business.m1 = {
  0: {emoji:"⚙️", subtitle:"Grade 10 · The eight functions that run every business",
    illusText:"Order groceries on an app and eight business functions work together in under an hour.",
    hook:{title:"Groceries in 60 minutes", body:"When you order groceries on a delivery app, a lot happens fast: buyers made sure stock was there, the app was marketed to you, staff were hired and trained to pick and deliver, money was handled, and the whole operation was planned by managers. Every business — from a spaza to a supermarket chain — needs the same <strong>business functions</strong>."},
    intro:"CAPS identifies eight <strong>business functions</strong>: <strong>general management</strong> (planning, organising, leading and controlling the whole business), <strong>purchasing</strong> (buying raw materials and stock), <strong>production</strong> (turning inputs into goods or services), <strong>marketing</strong> (identifying and satisfying customer needs), <strong>public relations</strong> (building a positive image), <strong>human resources</strong> (recruiting, training and managing people), <strong>administration</strong> (records and information) and <strong>financial</strong> (raising, using and controlling money). The functions depend on each other: a weakness in one affects them all.",
    concepts:[
      {t:"green", title:"🧠 Management", body:"Coordinates all the other functions towards the business's goals."},
      {t:"teal", title:"🔗 Interdependence", body:"Marketing promises a delivery time; purchasing and production must deliver it; finance pays for it."},
      {t:"gold", title:"🏪 Small businesses", body:"In a spaza, one person may do all eight functions — but each still has to be done."},
    ],
    examples:[
      {title:"Name the function", body:"Placing an order for 200 loaves from a bakery.", answer:"<strong>Purchasing</strong>."},
      {title:"Name the function", body:"Interviewing applicants for a delivery-driver job.", answer:"<strong>Human resources</strong>."},
      {title:"Name the function", body:"Sponsoring a local soccer team to build goodwill.", answer:"<strong>Public relations</strong> (it may also support marketing)."},
    ],
    mistakes:["Confusing marketing (selling to customers) with public relations (building the business's image).","Confusing purchasing (buying) with production (making).","Listing functions without examples."],
    callout:{title:"Careers", body:"Each function is a career path: buyer, production manager, marketer, PR officer, HR practitioner, administrator, accountant."},
    activity:"Choose a business you know. Give one example of each of the eight functions in that business.",
    activityAnswer:"Example for a taxi association: management (route planning), purchasing (fuel, tyres), production (transport service), marketing (route signs), PR (community meetings), HR (driver hiring), administration (permits), financial (fare collection and banking).",
    examTip:"Questions often give a scenario and ask you to identify the function — quote the words from the scenario that show it.",
    keyterms:[{w:"Business function",d:"A group of related activities within a business"},{w:"Purchasing",d:"Buying goods and materials the business needs"},{w:"Public relations",d:"Building a positive image with the public"}],
    quiz:[
      {q:"Recruiting and training staff is the:",opts:["Marketing function","Human resources function","Financial function","Production function"],a:1,et:"HR."},
      {q:"Turning raw materials into products is the:",opts:["Production function","Purchasing function","Administration function","PR function"],a:0,et:"Production."},
      {q:"How many business functions does CAPS list?",opts:["4","6","8","10"],a:2,et:"Eight functions."},
    ],
    conclusion:"Eight functions, one business. When they work together, customers get what they were promised."},

  1: {emoji:"📣", subtitle:"Grade 10–11 · The 4 Ps and selling in South Africa",
    illusText:"South African adverts are famous for making people laugh — and then buy.",
    hook:{title:"Adverts everyone talks about", body:"Some South African brands are famous for cheeky, funny adverts that comment on the news, load shedding or politics. People share them on WhatsApp for free — that's marketing doing its job. But a clever advert is only one part. A brand also needs the right <strong>product</strong>, <strong>price</strong> and <strong>place</strong>. Together with <strong>promotion</strong>, these are the <strong>4 Ps of marketing</strong>."},
    intro:"<strong>Marketing</strong> identifies and satisfies customer needs profitably. The <strong>marketing mix (4 Ps)</strong>: <strong>Product</strong> (quality, design, packaging, brand), <strong>Price</strong> (pricing strategy), <strong>Place</strong> (distribution — where and how customers get it) and <strong>Promotion</strong> (advertising, social media, sales promotions, personal selling, publicity). Businesses choose a <strong>target market</strong> and position their product for it. Pricing strategies include <strong>penetration pricing</strong> (low price to enter a market), <strong>price skimming</strong> (high price for a new product), and psychological pricing (R99.99). The <strong>Consumer Protection Act 68 of 2008</strong> protects customers from misleading marketing.",
    concepts:[
      {t:"green", title:"🎯 Target market", body:"A specific group of customers: e.g. students, taxi commuters, young parents. Marketing must speak to them."},
      {t:"teal", title:"💲 Pricing strategies", body:"Penetration (low to win customers), skimming (high at launch), competitive (match rivals), psychological (R49.99)."},
      {t:"gold", title:"📱 Promotion today", body:"Social media, influencers and WhatsApp sharing reach audiences cheaply — but must be honest under the CPA."},
    ],
    examples:[
      {title:"Pricing strategy", body:"A new data provider launches with prices far below competitors to attract users.", answer:"<strong>Penetration pricing</strong>."},
      {title:"Which P?", body:"A cold-drink brand stocks its drinks in spaza fridges across townships.", answer:"<strong>Place</strong> (distribution)."},
      {title:"CPA", body:"An advert says “free phone” but the small print requires a 36-month contract.", answer:"Possibly <strong>misleading marketing</strong> under the Consumer Protection Act."},
    ],
    mistakes:["Thinking marketing is only advertising.","Mixing up penetration pricing and price skimming.","Ignoring the target market when suggesting promotions."],
    callout:{title:"Know your customer", body:"The best marketers in South Africa understand language, culture and budget — a campaign in isiZulu on community radio can beat an expensive TV ad."},
    activity:"Design a marketing mix (4 Ps) for a new school-tuck-shop snack.",
    activityAnswer:"Product: healthy, tasty snack in a small pack. Price: R10 (affordable for learners). Place: tuck shop and nearby spazas. Promotion: posters, a launch tasting day, Instagram/TikTok posts by learners.",
    examTip:"When asked to apply the 4 Ps, give one specific example for each P linked to the business in the question.",
    keyterms:[{w:"Marketing mix",d:"Product, price, place and promotion"},{w:"Target market",d:"The group of customers a business aims to serve"},{w:"Penetration pricing",d:"Setting a low price to enter a market"}],
    quiz:[
      {q:"The 4 Ps are product, price, place and:",opts:["People","Promotion","Profit","Packaging"],a:1,et:"Promotion."},
      {q:"A high launch price for a new gadget is:",opts:["Penetration pricing","Price skimming","Psychological pricing","Discounting"],a:1,et:"Skimming early buyers."},
      {q:"South Africa's law protecting consumers is the:",opts:["Labour Relations Act","Consumer Protection Act","Companies Act","B-BBEE Act"],a:1,et:"Act 68 of 2008."},
    ],
    conclusion:"Marketing is the whole package: the right product, at the right price, in the right place, promoted the right way."},

  2: {emoji:"👷", subtitle:"Grade 10–12 · People, rights and labour law",
    illusText:"Work 4 hours of overtime at R40 an hour and the law says you earn R240, not R160.",
    hook:{title:"Overtime at month-end", body:"Sizwe works at a hardware store. At month-end stocktake, the manager asks him to work 4 extra hours. His hourly rate is R40. Does he earn R160? No — the law says overtime is paid at 1.5 times the normal rate: <strong>R240</strong>. Knowing labour law protects workers and keeps businesses out of trouble."},
    intro:"The <strong>human resources</strong> function recruits, selects, trains, pays and develops employees. Key labour laws: the <strong>Labour Relations Act (LRA) 66 of 1995</strong> — rights to join unions, collective bargaining, strikes and dispute resolution through the <strong>CCMA</strong>; the <strong>Basic Conditions of Employment Act (BCEA) 75 of 1997</strong> — maximum 45 ordinary hours a week, overtime at 1.5× the normal rate, leave rules; the <strong>Employment Equity Act 55 of 1998</strong> — fair treatment and affirmative action; the <strong>Skills Development Act 97 of 1998</strong>; and the <strong>National Minimum Wage Act (2018)</strong>. The national minimum wage is adjusted each year (R28.79 per hour from March 2025 — check the current rate).",
    concepts:[
      {t:"green", title:"🧑‍💼 Recruitment and selection", body:"Job analysis → advertise → shortlist → interview → appoint → induction."},
      {t:"teal", title:"⚖️ The CCMA", body:"The Commission for Conciliation, Mediation and Arbitration resolves workplace disputes, such as unfair dismissal."},
      {t:"gold", title:"⏰ BCEA basics", body:"45 ordinary hours a week; overtime 1.5×; paid annual, sick and family-responsibility leave."},
    ],
    examples:[
      {title:"Overtime", body:"4 hours overtime at R40 per hour.", answer:"4 × 40 × 1.5 = <strong>R240</strong>."},
      {title:"Minimum wage", body:"A worker earns the minimum wage of R28.79 for a 45-hour week.", answer:"45 × 28.79 = <strong>R1 295.55</strong> per week."},
      {title:"Dispute", body:"Sizwe believes he was dismissed unfairly. Where can he go?", answer:"He can refer the dispute to the <strong>CCMA</strong>."},
    ],
    formula:"Overtime pay = Hours × Hourly rate × 1.5",
    mistakes:["Mixing up the LRA (unions, disputes) and the BCEA (working conditions).","Forgetting the 1.5× overtime rate.","Using an outdated minimum-wage figure without saying so."],
    callout:{title:"Know your rights", body:"You'll be a worker or an employer one day. A payslip, a written contract and UIF registration are basic rights."},
    activity:"A shop assistant earns R35 an hour and works 45 ordinary hours plus 5 hours overtime in a week. Calculate her weekly pay.",
    activityAnswer:"Ordinary: 45 × 35 = R1 575. Overtime: 5 × 35 × 1.5 = R262.50. Total = <strong>R1 837.50</strong>.",
    examTip:"Name the Act correctly (with its number) and link each right or duty to that Act.",
    keyterms:[{w:"LRA",d:"Labour Relations Act — unions, strikes and disputes"},{w:"BCEA",d:"Basic Conditions of Employment Act — hours, leave and overtime"},{w:"CCMA",d:"Body that resolves labour disputes"}],
    quiz:[
      {q:"Overtime is normally paid at:",opts:["The normal rate","1.5 times the normal rate","Half the normal rate","3 times the normal rate"],a:1,et:"Under the BCEA."},
      {q:"Unfair dismissal disputes go to the:",opts:["SARS","CCMA","CIPC","JSE"],a:1,et:"Conciliation, mediation and arbitration."},
      {q:"Maximum ordinary working hours per week under the BCEA:",opts:["40","45","50","60"],a:1,et:"45 hours."},
    ],
    conclusion:"People are a business's most important resource. Labour law sets the rules that protect both sides."},

  3: {emoji:"💰", subtitle:"Grade 10–11 · Raising money and making it last",
    illusText:"Fixed costs R6 000, price R25, variable cost R10: sell 400 units a month just to break even.",
    hook:{title:"How many prints to break even?", body:"Khanyi opens a T-shirt printing business. Rent and other fixed costs are R6 000 a month. Each T-shirt sells for R25 and costs R10 to make. How many must she sell before she makes any profit at all? <strong>400 a month</strong>. The financial function helps owners raise money, budget and understand when a business starts paying off."},
    intro:"The <strong>financial function</strong> raises capital, plans spending and controls money. <strong>Sources of finance</strong>: own capital (savings), loans from banks, overdrafts, trade credit from suppliers, hire purchase and leasing, investors buying shares, and grants (e.g. from the National Youth Development Agency). <strong>Budgets</strong> plan income and spending. <strong>Break-even</strong> is where total income equals total costs: <strong>break-even quantity = fixed costs ÷ (selling price − variable cost per unit)</strong>. Above that, each unit earns profit.",
    concepts:[
      {t:"green", title:"🏦 Short vs long-term finance", body:"Overdrafts and trade credit for day-to-day needs; loans and share capital for equipment and expansion."},
      {t:"teal", title:"📊 Budgets", body:"A cash budget shows expected cash in and out each month — vital for small businesses."},
      {t:"gold", title:"⚖️ Break-even", body:"Each unit sold contributes (price − variable cost) towards fixed costs, then towards profit."},
    ],
    examples:[
      {title:"Break-even", body:"Fixed costs R6 000; price R25; variable cost R10.", answer:"6 000 ÷ (25 − 10) = <strong>400 T-shirts</strong> a month."},
      {title:"Profit above break-even", body:"Khanyi sells 500 T-shirts.", answer:"(500 − 400) × 15 = <strong>R1 500 profit</strong>."},
      {title:"Choose the finance", body:"Khanyi needs R40 000 for a new printing machine.", answer:"A <strong>long-term option</strong>: a bank loan, hire purchase or an investor — not an overdraft."},
    ],
    formula:"Break-even quantity = Fixed costs ÷ (Selling price − Variable cost per unit)",
    mistakes:["Using an overdraft for long-term purchases.","Forgetting fixed costs when calculating profit.","Confusing profit with cash in the bank."],
    callout:{title:"Funding for young people", body:"The National Youth Development Agency (NYDA) and other programmes offer grants and support to young entrepreneurs — always check current requirements."},
    activity:"A vetkoek stall has fixed costs of R1 800 a month. Each vetkoek sells for R8 and costs R3 to make. Calculate the break-even quantity.",
    activityAnswer:"1 800 ÷ (8 − 3) = <strong>360 vetkoek</strong> a month.",
    examTip:"Show the formula, substitution and answer with units. Then interpret: what does the number mean for the business?",
    keyterms:[{w:"Break-even point",d:"Where total income equals total costs"},{w:"Fixed costs",d:"Costs that stay the same regardless of output (rent)"},{w:"Variable costs",d:"Costs that change with output (materials)"}],
    quiz:[
      {q:"Fixed costs R3 000, price R20, variable cost R5. Break-even:",opts:["150","200","600","1 000"],a:1,et:"3 000 ÷ 15 = 200."},
      {q:"Which is a fixed cost?",opts:["Fabric for each T-shirt","Monthly rent","Ink per print","Packaging per item"],a:1,et:"It doesn't change with output."},
      {q:"Best source for buying a delivery van:",opts:["Overdraft","Long-term loan or hire purchase","Petty cash","Trade credit"],a:1,et:"Match long-term assets with long-term finance."},
    ],
    conclusion:"Know your fixed costs, your margins and your break-even point — and match finance to the need."},

  4: {emoji:"🏭", subtitle:"Grade 10–11 · Making goods and services efficiently",
    illusText:"Toyota's Prospecton plant in Durban builds the Hilux — South Africa's best-selling bakkie.",
    hook:{title:"A bakkie off the line", body:"At Toyota's plant in Prospecton, Durban, a new Hilux rolls off the production line every few minutes. Each worker and robot does one task, in the same order, all day. That's <strong>mass production</strong>. A tailor making one wedding dress works completely differently. The <strong>operations function</strong> decides how a business turns inputs into goods or services."},
    intro:"The <strong>operations (production) function</strong> converts inputs (raw materials, labour, capital) into outputs (goods and services). <strong>Production systems</strong>: <strong>job production</strong> (one unique item, e.g. a tailored suit), <strong>batch production</strong> (groups of identical items, e.g. a bakery baking 200 loaves of one type, then another), and <strong>mass/flow production</strong> (continuous, large volumes, e.g. cars, cold drinks). <strong>Quality control</strong> checks finished products; <strong>quality assurance</strong> builds quality into every step; <strong>Total Quality Management (TQM)</strong> involves everyone in continuous improvement. <strong>Productivity = output ÷ input</strong>.",
    concepts:[
      {t:"green", title:"🧵 Job production", body:"Unique, high-quality, made to order — skilled labour, higher cost per item."},
      {t:"teal", title:"🍞 Batch production", body:"Groups of identical items; machines are reset between batches."},
      {t:"gold", title:"🚗 Mass production", body:"Continuous, standardised, high volume — low cost per unit but expensive equipment."},
    ],
    examples:[
      {title:"Name the system", body:"A furniture maker builds a custom kitchen for one client.", answer:"<strong>Job production</strong>."},
      {title:"Productivity", body:"A bakery produces 1 200 loaves in 8 hours.", answer:"1 200 ÷ 8 = <strong>150 loaves per hour</strong>."},
      {title:"Quality", body:"What's the difference between quality control and quality assurance?", answer:"Control <strong>inspects finished products</strong>; assurance <strong>builds quality into every stage</strong>."},
    ],
    formula:"Productivity = Output ÷ Input",
    mistakes:["Confusing batch and mass production.","Thinking quality control and quality assurance are the same.","Forgetting service businesses also have operations."],
    callout:{title:"Local manufacturing", body:"Manufacturing creates jobs. Buying locally made products supports South African factories and workers."},
    activity:"Classify each as job, batch or mass production: (a) a wedding cake; (b) 500 school jerseys in one size; (c) cold drinks on a bottling line.",
    activityAnswer:"(a) Job. (b) Batch. (c) Mass/flow.",
    examTip:"When recommending a production system, link it to the product, the volume needed and the cost.",
    keyterms:[{w:"Mass production",d:"Continuous production of large volumes of identical products"},{w:"Quality assurance",d:"Building quality into every stage of production"},{w:"Productivity",d:"Output per unit of input"}],
    quiz:[
      {q:"A tailor making one suit uses:",opts:["Job production","Batch production","Mass production","Flow production"],a:0,et:"Unique and made to order."},
      {q:"900 units in 6 hours. Productivity per hour:",opts:["100","150","5 400","900"],a:1,et:"900 ÷ 6 = 150."},
      {q:"Inspecting finished products is:",opts:["Quality assurance","Quality control","TQM","Marketing"],a:1,et:"Checks at the end."},
    ],
    conclusion:"Choose the production system that fits the product, then build quality into every step."},

  5: {emoji:"🏉", subtitle:"Grade 10–12 · Leading people towards a goal",
    illusText:"Siya Kolisi captained the Springboks to two Rugby World Cup titles, in 2019 and 2023.",
    hook:{title:"The captain from Zwide", body:"Siya Kolisi grew up in Zwide township near Gqeberha and became the Springboks' first black Test captain. He led the team to Rugby World Cup wins in <strong>2019</strong> and <strong>2023</strong>. Coaches planned, organised and controlled; Kolisi led by example and united a diverse team. Every business needs the same four <strong>management tasks</strong> — and good leadership."},
    intro:"<strong>Management</strong> is getting work done through people to achieve goals. The four <strong>management tasks</strong>: <strong>planning</strong> (setting goals and deciding how to reach them), <strong>organising</strong> (arranging people and resources), <strong>leading</strong> (motivating and guiding people) and <strong>controlling</strong> (checking progress and correcting). Management levels: <strong>top</strong> (strategic, long-term), <strong>middle</strong> (tactical) and <strong>lower</strong> (operational, day-to-day). <strong>Leadership styles</strong> include <strong>autocratic</strong> (leader decides alone), <strong>democratic</strong> (team participates), <strong>laissez-faire</strong> (team decides with little guidance), <strong>transformational</strong> and <strong>charismatic</strong>. Management focuses on systems; leadership focuses on people and vision.",
    concepts:[
      {t:"green", title:"🗺️ Four tasks", body:"Plan → organise → lead → control, in a continuous cycle."},
      {t:"teal", title:"🪜 Three levels", body:"Top (CEO: strategy), middle (department heads: tactics), lower (supervisors: daily operations)."},
      {t:"gold", title:"🧭 Styles", body:"No style is always best: autocratic suits emergencies; democratic suits skilled, motivated teams."},
    ],
    examples:[
      {title:"Name the task", body:"A manager compares monthly sales with targets and changes the plan.", answer:"<strong>Controlling</strong>."},
      {title:"Name the style", body:"A supervisor asks the team for ideas before deciding on a new shift roster.", answer:"<strong>Democratic</strong> leadership."},
      {title:"When to be autocratic", body:"When is an autocratic style appropriate?", answer:"In an <strong>emergency</strong> (e.g. a fire evacuation) or with new, inexperienced staff who need clear instructions."},
    ],
    mistakes:["Using “management” and “leadership” as if they mean exactly the same thing.","Saying one leadership style is always best.","Mixing up the levels of management."],
    callout:{title:"Leaders everywhere", body:"Class representatives, team captains and stokvel chairpersons all plan, organise, lead and control. You're practising management already."},
    activity:"Think of a leader you admire (a coach, teacher, parent or public figure). Describe their leadership style with two examples.",
    activityAnswer:"A strong answer names a style (e.g. democratic, transformational), gives two specific behaviours as evidence and explains why the style works in that situation.",
    examTip:"For leadership-style questions, identify the style, quote evidence from the scenario and give an advantage and disadvantage.",
    keyterms:[{w:"Management tasks",d:"Planning, organising, leading and controlling"},{w:"Autocratic leadership",d:"The leader makes decisions alone"},{w:"Democratic leadership",d:"Team members take part in decisions"}],
    quiz:[
      {q:"Checking progress against goals is:",opts:["Planning","Organising","Leading","Controlling"],a:3,et:"Then correcting where needed."},
      {q:"A leader who decides alone is:",opts:["Democratic","Autocratic","Laissez-faire","Transformational"],a:1,et:"Autocratic."},
      {q:"Long-term strategy is set by:",opts:["Top management","Middle management","Lower management","Customers"],a:0,et:"For example the CEO and board."},
    ],
    conclusion:"Managers plan, organise, lead and control. Great leaders also inspire — on the field and in business."},
};

