LESSON_DB.business.m0[1].svg = "<svg viewBox=\"0 0 400 220\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"400\" height=\"220\" fill=\"#0d1024\"/><text x=\"16.0\" y=\"24.0\" fill=\"#00C2D4\" font-size=\"12\" text-anchor=\"start\" font-weight=\"700\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">PARTNERSHIP: SHARING PROFIT</text><rect x=\"40.0\" y=\"60.0\" width=\"200.0\" height=\"36.0\" rx=\"4\" fill=\"rgba(0,214,143,.35)\" stroke=\"#00D68F\" stroke-width=\"2\" opacity=\"1\"/><text x=\"140.0\" y=\"83.0\" fill=\"#E2E8F0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"800\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">Lerato 3 parts · R72 000</text><rect x=\"240.0\" y=\"60.0\" width=\"133.0\" height=\"36.0\" rx=\"4\" fill=\"rgba(0,194,212,.35)\" stroke=\"#00C2D4\" stroke-width=\"2\" opacity=\"1\"/><text x=\"306.0\" y=\"83.0\" fill=\"#E2E8F0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"800\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">Kabelo 2 · R48 000</text><text x=\"200.0\" y=\"125.0\" fill=\"#FFB800\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"800\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">R120 000 ÷ 5 parts = R24 000 a part</text><text x=\"200.0\" y=\"170.0\" fill=\"#FF6B35\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"800\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">unlimited + joint liability · no continuity</text></svg>";
